function applyTheme(theme){document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;document.querySelectorAll('.theme-switch').forEach(button=>{let dark=theme==='dark';button.querySelector('.theme-icon').textContent=dark?'☀':'☾';button.querySelector('.theme-label').textContent=dark?'浅色模式':'深色模式';button.setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式');button.setAttribute('aria-pressed',String(dark))})}document.querySelectorAll('.theme-switch').forEach(button=>button.addEventListener('click',()=>{let theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('token-field-theme',theme)}catch{}applyTheme(theme)}));applyTheme(document.documentElement.dataset.theme||'light');
